import java.util.*;import java.util.jar.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
public final class SourceGroundOriginDelta {
 static final String P="local/lito381/server/",E=P+"BattleGroundEffects",L=E+"$Lease",U=E+"$Pulse",H=P+"GameHub",T=H+"$GroundTick",PC=P+"ClientSession",C=P+"NativeAreaMaterialAction$Context",R=P+"NativeSourceRawDamage",A=R+"$Action",N=P+"NativeSourceGroundOrigin";
 static final List<String>TARGETS=List.of(E,L,U,H,T,PC,C,R,A);
 static void need(boolean v,String why){if(!v)throw new AssertionError(why);}
 static void loads(MethodNode m,MethodInsnNode call,int...opSlot){AbstractInsnNode n=call;for(int i=opSlot.length-2;i>=0;i-=2){n=FreezeAcceptedMethods.prev(n);need(n instanceof VarInsnNode v&&v.getOpcode()==opSlot[i]&&v.var==opSlot[i+1],"exact original operand locals");}for(int i=0;i<opSlot.length/2;i++)m.instructions.remove(FreezeAcceptedMethods.prev(call));}
 static void restore(MethodInsnNode c,int opcode,String owner,String name,String desc){c.setOpcode(opcode);c.owner=owner;c.name=name;c.desc=desc;}
 static void undo(String owner,MethodNode m){for(var node:m.instructions.toArray())if(node instanceof MethodInsnNode call){
  if(call.owner.equals(L)&&call.name.equals("<init>")&&call.desc.contains(E+";")){loads(m,call,ALOAD,0);call.desc="(IJIIIJJI)V";}
  else if(call.owner.equals(U)&&call.name.equals("<init>")&&call.desc.contains(E+";")){loads(m,call,ALOAD,0,ALOAD,6);call.desc="(IJJZ)V";}
  else if(call.owner.equals(T)&&call.name.equals("<init>")&&call.desc.contains(U+";")){loads(m,call,ALOAD,10);call.desc="(JL"+PC+";L"+PC+";ZI)V";}
  else if(call.owner.equals(N))switch(call.name){
   case "reset"->{need(owner.equals(E)&&List.of("<init>","clear").contains(m.name),"only epoch lifecycle");loads(m,call,ALOAD,0);m.instructions.remove(call);}
   case "cast"->{need(owner.equals(H)&&m.name.equals("placeGroundSpell"),"original ground factory");loads(m,call,ALOAD,0,LLOAD,1,ALOAD,3);restore(call,INVOKEVIRTUAL,E,"cast","(L"+P+"BattleSpellCatalog$GroundSpell;JIIIIL"+P+"ArenaMapCatalog$Arena;J)L"+E+"$CastResult;");}
   case "advance"->{need(owner.equals(H)&&m.name.equals("groundTicks"),"original periodic scan");loads(m,call,ALOAD,0);restore(call,INVOKEVIRTUAL,E,"advance","(JLjava/util/List;)Ljava/util/List;");}
   case "caster"->{need(owner.equals(H)&&m.name.equals("groundTicks"),"original caster local");loads(m,call,ALOAD,10);m.instructions.remove(call);}
   case "dispatch"->{need(owner.equals(H)&&m.name.equals("groundTickSafely"),"actual clock PC port");loads(m,call,ALOAD,4);restore(call,INVOKEVIRTUAL,PC,"serverGroundPulse","(JL"+PC+";I)V");}
   case "damage"->{need(owner.equals(PC)&&m.name.equals("serverGroundPulse"),"single original PC HP leaf");restore(call,INVOKEVIRTUAL,PC,"takePlayerDamage","(IL"+PC+";)V");}
   case "allowFrame"->{need(owner.equals(R)&&m.name.equals("allowFrame"),"existing final raw packet guard");loads(m,call,ALOAD,0,ALOAD,1);var jump=FreezeAcceptedMethods.next(call);var zero=FreezeAcceptedMethods.next(jump);var ret=FreezeAcceptedMethods.next(zero);need(jump instanceof JumpInsnNode j&&j.getOpcode()==IFNE&&zero.getOpcode()==ICONST_0&&ret.getOpcode()==IRETURN,"reject-only final scene gate");for(var n:List.of(call,jump,zero,ret))m.instructions.remove(n);}
   case "close"->{need(owner.equals(A)&&m.name.equals("close"),"original completion cleanup");var field=FreezeAcceptedMethods.prev(call);var self=FreezeAcceptedMethods.prev(field);need(field instanceof FieldInsnNode f&&f.owner.equals(A)&&f.name.equals("c")&&field.getOpcode()==GETFIELD&&self instanceof VarInsnNode v&&v.var==0&&v.getOpcode()==ALOAD,"same owning Context cleanup");m.instructions.remove(field);m.instructions.remove(self);m.instructions.remove(call);}
   default->throw new AssertionError("unreviewed delta "+call.name);
  }
 }}
 public static void main(String[]a)throws Exception{try(var base=new JarFile(a[0]);var child=new JarFile(a[1])){var original=new HashSet<String>();var changed=new HashSet<String>();for(var e:Collections.list(base.entries())){original.add(e.getName());var n=child.getJarEntry(e.getName());need(n!=null,"all original entries retained");if(!Arrays.equals(base.getInputStream(e).readAllBytes(),child.getInputStream(n).readAllBytes()))changed.add(e.getName());}var expected=new HashSet<String>();for(String n:TARGETS)expected.add(n+".class");need(changed.equals(expected),"only nine original lifecycle owners changed");int count=0;
 for(String owner:TARGETS){var before=FreezeSourceTargetDelta.read(base,owner);var after=FreezeSourceTargetDelta.read(child,owner);int extra=owner.equals(E)?4:List.of(L,U,T,C).contains(owner)?1:0;need(after.fields.size()==before.fields.size()+extra,"bounded original-owner fields");for(int i=0;i<before.fields.size();i++){var x=before.fields.get(i);var y=after.fields.get(i);need(x.name.equals(y.name)&&x.desc.equals(y.desc)&&x.access==y.access&&Objects.equals(x.value,y.value),"original fields retained");}for(var f:after.fields.subList(before.fields.size(),after.fields.size()))need(f.desc.equals("Ljava/lang/Object;")&&(owner.equals(E)||owner.equals(C)?f.access==ACC_VOLATILE:f.access==ACC_FINAL),"detached metadata visibility");need(after.methods.size()==before.methods.size()+(List.of(L,U,T).contains(owner)?1:0),"only three delegating metadata constructors");for(var old:before.methods){var now=after.methods.stream().filter(x->x.name.equals(old.name)&&x.desc.equals(old.desc)).findFirst().orElseThrow();undo(owner,now);need(old.access==now.access&&Arrays.equals(FreezeSourceTargetDelta.body(before,old,old.name,old.access),FreezeSourceTargetDelta.body(after,now,old.name,old.access)),"independent inverse "+owner+old.name+old.desc);count++;}}
 var helpers=new HashSet<String>();for(var e:Collections.list(child.entries()))if(!original.contains(e.getName())){helpers.add(e.getName());need(e.getName().startsWith(N)&&e.getName().endsWith(".class"),"only ground helper/immutable records");var c=FreezeSourceTargetDelta.read(child,e.getName().substring(0,e.getName().length()-6));for(var field:c.fields)need(!field.desc.contains("Context")&&!field.desc.contains("Scope")&&!field.desc.contains("Frame")&&!field.desc.contains("Action"),"no queued Context or invocation scope");for(var m:c.methods)for(var n:m.instructions){if(n instanceof TypeInsnNode t&&t.getOpcode()==NEW)need(!t.desc.contains("Thread")&&!t.desc.contains("Timer")&&!t.desc.contains("Executor")&&!t.desc.equals(H)&&!t.desc.equals(PC),"reuse original clocks and actors");if(n instanceof MethodInsnNode call)need(!call.owner.startsWith("java/sql/")&&!call.owner.startsWith("java/nio/file/")&&!call.owner.contains("Random")&&!call.owner.contains("Repository")&&!call.owner.contains("GameStateStore"),"no persistence or new calculation");}}
 need(helpers.size()==6,"one helper plus five detached record types");System.out.println("PASS independent ground origin inverse: "+count+" original methods; exact old factory/clock/HP/presentation bodies retained around nine owned metadata/guard deltas");}}
}
